2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records, on the owner being created, how many owners already exist that share the same
9	 * firstName and lastName (compared case-insensitively). The count is a snapshot taken
10	 * before this owner is saved, so it counts only the pre-existing namesakes. Runs before
11	 * {@link SaveOwner}.
12	 */
13	public class AssignNamesakeCount {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String firstName = normalize(owner.getFirstName());
17	        String lastName = normalize(owner.getLastName());
18	        int count = 0;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (normalize(existing.getFirstName()).equals(firstName)
21	                    && normalize(existing.getLastName()).equals(lastName)) {
22	                count++;
23	            }
24	        }
25	        owner.setNamesakeCount(count);
26	    }
27	
28	    private static String normalize(String value) {
29	        return value == null ? "" : value.trim().toLowerCase();
30	    }
31	}
