2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records, on the owner being created, the size of its household — the number of owners sharing the
9	 * same {@code householdId} once this create completes. Runs after {@link AssignHousehold}, which has
10	 * already assigned the shared {@code householdId} to the new owner and any existing members, but
11	 * before {@link SaveOwner} persists the new owner; so the count is the existing members carrying the
12	 * id plus one for the owner being created.
13	 *
14	 * <p>An owner with no {@code householdId} (no shared household) has a household size of one. The stored
15	 * value lets {@link org.springframework.samples.petclinic.mapper.OwnerMapper} derive the {@code GOLD}
16	 * membership tier for households of three or more members.
17	 */
18	public class AssignHouseholdSize {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        if (householdId == null) {
23	            owner.setHouseholdSize(1);
24	            return;
25	        }
26	        int count = 1; // the owner being created, not yet saved
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (householdId.equals(existing.getHouseholdId())) {
29	                count++;
30	            }
31	        }
32	        owner.setHouseholdSize(count);
33	    }
34	}
